with flagged as (select *, case when lag(event_time) over (partition by page order by event_time, id) is null or event_time > lag(event_time) over (partition by page order by event_time, id) + interval '60' day then 1 else 0 end as is_new_session from web_events), islands as (select id, page, event_time, sum(is_new_session) over (partition by page order by event_time, id rows between unbounded preceding and current row) as island_id from flagged) select page, approx_percentile(island_id, 0.9) as island_id_p90, size(collect_set(page)) as num_pages, min(event_time) as started_at from islands group by page having size(collect_set(page)) < 1000
